    new Panel(exceptions, "Exceptions to investigate"),
    new TextBlock("[muted]Skipped cells are ports that host does not need.[/]")) { Gap = 1 };

// Behaviour: print the collected observations once; collectors belong before the layout.
Terminal.Write(report);

